public record PairMatch(int leftIndex, int rightIndex, int leftValue, int rightValue) {

    public PairMatch {
        if (leftIndex < 0) {
            throw new IllegalArgumentException("leftIndex must not be negative");
        }

        if (rightIndex <= leftIndex) {
            throw new IllegalArgumentException("rightIndex must be greater than leftIndex");
        }
    }

    public long sum() {
        return (long) leftValue + rightValue;
    }
}

import java.util.Arrays;
import java.util.Optional;

public final class SortedIntArray {

    private static final SortedIntArray EMPTY = new SortedIntArray(new int[0]);

    private final int[] values;

    private SortedIntArray(int[] values) {
        this.values = values;
    }

    public static SortedIntArray copyOf(int[] values) {
        validateSorted(values);
        if (values.length == 0) {
            return EMPTY;
        }

        return new SortedIntArray(Arrays.copyOf(values, values.length));
    }

    public static SortedIntArray of(int... values) {
        return copyOf(values);
    }

    public int size() {
        return values.length;
    }

    public Optional<PairMatch> findPairWithSum(long target) {
        MatchIndexes matchIndexes = findMatchIndexes(target);
        if (matchIndexes == null) {
            return Optional.empty();
        }

        return Optional.of(matchIndexes.toPairMatch(values));
    }

    public boolean hasPairWithSum(long target) {
        return findMatchIndexes(target) != null;
    }

    public int[] toArray() {
        return Arrays.copyOf(values, values.length);
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }

        if (!(other instanceof SortedIntArray that)) {
            return false;
        }

        return Arrays.equals(values, that.values);
    }

    @Override
    public int hashCode() {
        return Arrays.hashCode(values);
    }

    @Override
    public String toString() {
        return Arrays.toString(values);
    }

    private boolean canContainPairMatching(long target) {
        return values.length >= 2
            && target >= minimumPairSum()
            && target <= maximumPairSum();
    }

    private MatchIndexes findMatchIndexes(long target) {
        if (!canContainPairMatching(target)) {
            return null;
        }

        int left = 0;
        int right = values.length - 1;

        while (left < right) {
            long sum = sumAt(left, right);
            if (sum == target) {
                return new MatchIndexes(left, right);
            }

            if (sum < target) {
                left++;
            } else {
                right--;
            }
        }

        return null;
    }

    private long minimumPairSum() {
        return (long) values[0] + values[1];
    }

    private long maximumPairSum() {
        int lastIndex = values.length - 1;
        return (long) values[lastIndex - 1] + values[lastIndex];
    }

    private long sumAt(int leftIndex, int rightIndex) {
        return (long) values[leftIndex] + values[rightIndex];
    }

    private static void validateSorted(int[] values) {
        if (values == null) {
            throw new IllegalArgumentException("values must not be null");
        }

        for (int index = 1; index < values.length; index++) {
            if (values[index - 1] > values[index]) {
                throw new IllegalArgumentException(
                    "two-pointer search requires values sorted in nondecreasing order");
            }
        }
    }

    private record MatchIndexes(int leftIndex, int rightIndex) {
        private PairMatch toPairMatch(int[] values) {
            return new PairMatch(leftIndex, rightIndex, values[leftIndex], values[rightIndex]);
        }
    }
}

import java.util.Optional;

public final class TwoPointers {

    private TwoPointers() {
    }

    public static Optional<PairMatch> findPairWithSum(int[] sortedValues, long target) {
        return copySortedValues(sortedValues).findPairWithSum(target);
    }

    public static Optional<PairMatch> findPairWithSum(SortedIntArray sortedValues, long target) {
        return requireSortedValues(sortedValues).findPairWithSum(target);
    }

    public static boolean hasPairWithSum(int[] sortedValues, long target) {
        return copySortedValues(sortedValues).hasPairWithSum(target);
    }

    public static boolean hasPairWithSum(SortedIntArray sortedValues, long target) {
        return requireSortedValues(sortedValues).hasPairWithSum(target);
    }

    private static SortedIntArray copySortedValues(int[] sortedValues) {
        return SortedIntArray.copyOf(sortedValues);
    }

    private static SortedIntArray requireSortedValues(SortedIntArray sortedValues) {
        if (sortedValues == null) {
            throw new IllegalArgumentException("sortedValues must not be null");
        }

        return sortedValues;
    }
}

public final class TwoPointersTest {

    private TwoPointersTest() {
    }

    public static void main(String[] args) {
        shouldFindMatchingPair();
        shouldReturnEmptyWhenNoPairExists();
        shouldReturnEmptyForArraysWithFewerThanTwoValues();
        shouldReturnEmptyWhenTargetIsOutsidePossibleRange();
        shouldSupportRawArrayFacadeLookups();
        shouldSupportRawArrayFacadeBooleanChecks();
        shouldRejectUnsortedInput();
        shouldHandleIntegerOverflowSafely();
        shouldSupportTargetsBeyondIntegerRange();
        shouldDefensivelyCopyValidatedInput();
        shouldRejectNullSortedValueObjects();
        shouldBehaveLikeAValueObject();
    }

    private static void shouldFindMatchingPair() {
        SortedIntArray sortedValues = SortedIntArray.of(-3, -1, 0, 1, 2);
        PairMatch match = sortedValues.findPairWithSum(-2)
            .orElseThrow(() -> new AssertionError("Expected a matching pair"));

        assertMatch(match, 0, 3, -3, 1, -2);
    }

    private static void shouldReturnEmptyWhenNoPairExists() {
        assertNoMatch(SortedIntArray.of(1, 4, 8).findPairWithSum(6));
    }

    private static void shouldReturnEmptyForArraysWithFewerThanTwoValues() {
        assertNoMatch(SortedIntArray.of().findPairWithSum(0));
        assertNoMatch(SortedIntArray.of(5).findPairWithSum(10));
    }

    private static void shouldReturnEmptyWhenTargetIsOutsidePossibleRange() {
        SortedIntArray sortedValues = SortedIntArray.of(2, 4, 8, 16);

        assertNoMatch(sortedValues.findPairWithSum(5));
        assertNoMatch(sortedValues.findPairWithSum(30));
    }

    private static void shouldSupportRawArrayFacadeLookups() {
        PairMatch match = TwoPointers.findPairWithSum(new int[] {-3, -1, 0, 1, 2}, -2)
            .orElseThrow(() -> new AssertionError("Expected raw array facade to find a match"));

        assertMatch(match, 0, 3, -3, 1, -2);
    }

    private static void shouldSupportRawArrayFacadeBooleanChecks() {
        if (!TwoPointers.hasPairWithSum(new int[] {1, 3, 7, 9}, 10)) {
            throw new AssertionError("Expected raw array facade to report a matching pair");
        }

        if (TwoPointers.hasPairWithSum(new int[] {1, 3, 7, 9}, 13)) {
            throw new AssertionError("Expected raw array facade to report no matching pair");
        }
    }

    private static void shouldRejectUnsortedInput() {
        assertThrowsWithMessage(
            () -> SortedIntArray.of(3, 1, 2),
            "sorted",
            "Expected unsorted input to be rejected");
    }

    private static void shouldHandleIntegerOverflowSafely() {
        PairMatch match = SortedIntArray.of(-1, Integer.MAX_VALUE)
            .findPairWithSum(Integer.MAX_VALUE - 1)
            .orElseThrow(() -> new AssertionError("Expected overflow-safe matching pair"));

        assertEquals(Integer.MAX_VALUE - 1L, match.sum(), "overflow-safe sum");
    }

    private static void shouldSupportTargetsBeyondIntegerRange() {
        PairMatch match = SortedIntArray.of(Integer.MAX_VALUE, Integer.MAX_VALUE)
            .findPairWithSum(4_294_967_294L)
            .orElseThrow(() -> new AssertionError("Expected match for large long target"));

        assertEquals(4_294_967_294L, match.sum(), "large target sum");
    }

    private static void shouldDefensivelyCopyValidatedInput() {
        int[] sourceValues = {1, 2, 3, 9};
        SortedIntArray sortedValues = SortedIntArray.copyOf(sourceValues);
        sourceValues[3] = -10;

        if (!TwoPointers.hasPairWithSum(sortedValues, 10)) {
            throw new AssertionError("Expected validated copy to be isolated from caller mutations");
        }
    }

    private static void shouldRejectNullSortedValueObjects() {
        assertThrowsWithMessage(
            () -> TwoPointers.findPairWithSum((SortedIntArray) null, 0),
            "must not be null",
            "Expected null SortedIntArray to be rejected");
    }

    private static void shouldBehaveLikeAValueObject() {
        SortedIntArray first = SortedIntArray.of(1, 2, 3);
        SortedIntArray second = SortedIntArray.copyOf(new int[] {1, 2, 3});

        if (!first.equals(second)) {
            throw new AssertionError("Expected equal sorted arrays to compare by value");
        }

        assertEquals(first.hashCode(), second.hashCode(), "hash code");

        if (!"[1, 2, 3]".equals(first.toString())) {
            throw new AssertionError("Unexpected string representation: " + first);
        }
    }

    private static void assertMatch(
        PairMatch match,
        int expectedLeftIndex,
        int expectedRightIndex,
        int expectedLeftValue,
        int expectedRightValue,
        long expectedSum
    ) {
        assertEquals(expectedLeftIndex, match.leftIndex(), "left index");
        assertEquals(expectedRightIndex, match.rightIndex(), "right index");
        assertEquals(expectedLeftValue, match.leftValue(), "left value");
        assertEquals(expectedRightValue, match.rightValue(), "right value");
        assertEquals(expectedSum, match.sum(), "pair sum");
    }

    private static void assertNoMatch(java.util.Optional<PairMatch> match) {
        if (match.isPresent()) {
            throw new AssertionError("Expected no matching pair");
        }
    }

    private static void assertThrowsWithMessage(
        ThrowingRunnable action,
        String expectedMessageFragment,
        String failureMessage
    ) {
        try {
            action.run();
            throw new AssertionError(failureMessage);
        } catch (IllegalArgumentException expected) {
            if (!expected.getMessage().contains(expectedMessageFragment)) {
                throw new AssertionError("Unexpected validation message: " + expected.getMessage());
            }
        }
    }

    private static void assertEquals(long expected, long actual, String fieldName) {
        if (expected != actual) {
            throw new AssertionError(
                "Unexpected " + fieldName + ": expected " + expected + ", got " + actual);
        }
    }

    @FunctionalInterface
    private interface ThrowingRunnable {
        void run();
    }
}

